import { parseTags } from "./tags.js";

export function splitNotes(text: string): string[] {
  return text.split("\n");
}

/** The note lines that carry `tag`, matched without case and with or without the #. */
export function notesWithTag(text: string, tag: string): string[] {
  const wanted = tag.replace(/^#/, "").toLowerCase();
  return splitNotes(text).filter((line) => parseTags(line).includes(wanted));
}

  expect(splitNotes("buy milk\ncall home")).toEqual(["buy milk", "call home"]);
});

it("keeps the lines that carry a tag", () => {
  expect(notesWithTag("buy milk #home\nfile taxes #work", "#Home")).toEqual(["buy milk #home"]);
});

